//! Embeds the Windows application icon by linking the precompiled resource file
//! (assets/icon/dirlark.res, generated by tools/make_icons.py). MSVC `link.exe` and `lld-link`
//! accept `.res` input directly, so no resource compiler or extra crate is required. Other
//! targets (and the MinGW compile gate) are untouched.
use std::{env, path::PathBuf};

fn main() {
    let resource: PathBuf = [
        env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR"),
        "assets/icon/dirlark.res".into(),
    ]
    .iter()
    .collect();
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={}", resource.display());
    if env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows")
        && env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc")
    {
        println!("cargo:rustc-link-arg-bins={}", resource.display());
    }
}
